import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 200005;
    static final int MAX_INT = 1000000007;

    static long X, Y, totalCount, candidateA = -1, candidateB = -1;

    static void tryUpdate(long a, int b) {
        if (a < 0) return;
        if (candidateA == -1) {
            candidateA = a;
            candidateB = b;
            return;
        }
        long diff1 = Math.abs(candidateB * X - candidateA * Y) * b;
        long diff2 = Math.abs(b * X - a * Y) * candidateB;
        if (diff1 > diff2) {
            candidateA = a;
            candidateB = b;
        } else if (diff1 == diff2 && (b < candidateB || (b == candidateB && a < candidateA))) {
            candidateA = a;
            candidateB = b;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        X = sc.nextLong();
        Y = sc.nextLong();
        totalCount = sc.nextLong();

        for (int i = 1; i <= totalCount; i++) {
            long val = i * X / Y;
            tryUpdate(val - 1, i);
            tryUpdate(val, i);
            tryUpdate(val + 1, i);
        }
        System.out.println(candidateA + "/" + candidateB);
        sc.close();
    }
}
